#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n;
    cin >> n;

    int x = 1;
    while (2 * x <= n) x *= 2;

    vector<int> p;
    for (int i = 0; i < x; i++) p.push_back(i);
    for (int i = x - 1; i >= 0; i--) p.push_back(i);
    for (int i = x; i < 2 * x; i++) p.push_back(i);
    for (int i = 2 * x - 1; i >= x; i--) p.push_back(i);

    cout << (int)p.size() - 1 << '\n';
    for (int i = 1; i < (int)p.size(); i++)
        cout << (p[i] ^ p[i - 1]) << " \n"[i == (int)p.size() - 1];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) solve();
}

#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n;
    long long m, k;
    cin >> n >> m >> k;

    vector<long long> l(n), r(n), pref(n + 1);
    for (int i = 0; i < n; i++) {
        cin >> l[i] >> r[i];
        pref[i + 1] = pref[i] + r[i] - l[i] + 1;
    }

    auto f = [&](long long s) -> long long {
        long long e = s + m - 1;

        int i = lower_bound(r.begin(), r.end(), s) - r.begin();
        int j = upper_bound(l.begin(), l.end(), e) - l.begin() - 1;

        if (i > j) return 0;

        long long ans = pref[j + 1] - pref[i];
        ans -= max(0LL, s - l[i]);
        ans -= max(0LL, r[j] - e);
        return ans;
    };

    long long mx = -1, pos = 0;
    for (int i = 0; i < n; i++) {
        long long cur = f(l[i]);
        if (cur > mx) {
            mx = cur;
            pos = l[i];
        }
    }

    if (k > mx) {
        cout << -1 << '\n';
        return;
    }

    if (k == mx) {
        cout << pos << '\n';
        return;
    }

    long long low = pos, high = 1000000000000001LL;

    while (high - low > 1) {
        long long mid = (low + high) / 2;
        if (f(mid) > k) low = mid;
        else high = mid;
    }

    cout << high << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) solve();
}

#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n, k;
    cin >> n >> k;

    vector<int> a(n);
    int mx = 0;
    for (int &x : a) {
        cin >> x;
        mx = max(mx, x);
    }

    vector<int> freq(mx + 1);
    for (int x : a) freq[x]++;

    auto ok = [&](int c) {
        vector<int> cnt = freq;
        int alive = n, used = 0, H = mx;
        long long S = 1LL * k + n + 2LL * c - 1;

        while (alive > 0) {
            while (cnt[H] == 0) H--;

            if (H <= S) {
                cnt[H]--;
                alive--;
                S--;
            } else {
                if (used == c) return false;
                cnt[H]--;
                cnt[(H + 1) / 2] += 2;
                alive++;
                used++;
            }
        }
        return true;
    };

    int l = 0, r = max(0, mx - k);
    while (l < r) {
        int mid = (l + r) / 2;
        if (ok(mid)) r = mid;
        else l = mid + 1;
    }

    cout << n + 2 * l << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) solve();
}

#include <bits/stdc++.h>
using namespace std;

bool beautiful(vector<int>& a) {
    int n = a.size();
    vector<int> st, diff(n + 1);

    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.back()] < a[i])
            st.pop_back();

        if (!st.empty() && a[st.back()] == a[i]) {
            diff[st.back()]++;
            diff[i + 1]--;
        }
        st.push_back(i);
    }

    int cur = 0;
    for (int i = 0; i < n; i++) {
        cur += diff[i];
        if (cur == 0) return false;
    }
    return true;
}

void solve() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    if (beautiful(a)) {
        cout << 0 << '\n';
        return;
    }

    int pos = max_element(a.begin(), a.end()) - a.begin();
    int mx = a[pos];

    auto check = [&](int i, int x) {
        int old = a[i];
        a[i] = x;
        bool ok = beautiful(a);
        a[i] = old;
        if (ok) {
            cout << 1 << '\n';
            cout << i + 1 << ' ' << x << '\n';
        }
        return ok;
    };

    if (check(0, mx)) return;
    if (check(n - 1, mx)) return;
    if (check(pos, 1)) return;

    cout << 2 << '\n';
    cout << 1 << ' ' << mx << '\n';
    cout << n << ' ' << mx << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) solve();
}
